27	/**
28	 * Creates the initial layout for a Plotly figure with sensible defaults.
29	 */
30	export function createInitialLayout(figure: Figure): Partial<Plotly.Layout> {
31	  // Enable autosize if width is not specified
32	  const shouldAutoSize = figure.layout.width === undefined;
33	  return {
34	    autosize: shouldAutoSize,
35	    dragmode: "select",
36	    height: 540,
37	    // Prioritize user's config
38	    ...figure.layout,
39	  };
40	}
41	
42	/**
43	 * Computes the updated layout when the figure changes.
44	 * Preserves user-interaction values (dragmode, xaxis, yaxis) while
45	 * taking everything else from the new figure's layout.
46	 */
47	export function computeLayoutOnFigureChange(
48	  nextFigure: Figure,
49	  prevLayout: Partial<Plotly.Layout>,
50	): Partial<Plotly.Layout> {
51	  return {
52	    ...createInitialLayout(nextFigure),
53	    ...Objects.pick(prevLayout, PERSISTED_LAYOUT_KEYS),
54	  };
55	}
56	
57	/**
58	 * Computes which keys to omit from layout updates based on what changed.
59	 * If a key changed in the figure, we should update it even if it's normally omitted.
60	 */
61	export function computeOmitKeys(
62	  currentLayout: Partial<Plotly.Layout>,
63	  previousLayout: Partial<Plotly.Layout>,
64	): Set<keyof Plotly.Layout> {
65	  const omitKeys = new Set<keyof Plotly.Layout>(LAYOUT_OMIT_KEYS);
66	
67	  // If the key was updated externally (e.g. can be specifically passed in the config)
68	  // then we need to update the layout
69	  for (const key of omitKeys) {
70	    if (!isEqual(currentLayout[key], previousLayout[key])) {
71	      omitKeys.delete(key);
72	    }
73	  }
74	
75	  return omitKeys;
76	}
77	
78	/**
79	 * Computes the layout update when figure.layout changes.
80	 * Omits keys that shouldn't override user interactions unless they changed.
81	 */
82	export function computeLayoutUpdate(
83	  figureLayout: Partial<Plotly.Layout>,
84	  previousFigureLayout: Partial<Plotly.Layout>,
85	  prevLayout: Partial<Plotly.Layout>,
86	): Partial<Plotly.Layout> {
87	  const omitKeys = computeOmitKeys(figureLayout, previousFigureLayout);
88	  const layoutUpdate = Objects.omit(figureLayout, omitKeys);
89	  return { ...prevLayout, ...layoutUpdate };
90	}
