def _is_datetime_like(value: Any) -> bool:
    """Return whether a value is a datetime object or ISO datetime string."""
    import datetime

    if isinstance(value, (datetime.datetime, datetime.date)):
        return True
    if isinstance(value, str):
        try:
            datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))
            return True
        except (ValueError, AttributeError):
            return False
    return False


def _to_numeric_coord(value: Any) -> float | int:
    """Convert a datetime-like value to a numeric coordinate.

    Naive datetime objects (and naive ISO datetime strings) are treated as
    UTC, producing the same numeric value as a UTC-aware datetime object and a
    UTC ISO datetime string, regardless of the system timezone setting.

    Numeric values are returned unchanged so this can be used uniformly for
    both datetime and numeric axes.
    """
    import datetime

    dt = value
    if isinstance(value, str):
        dt = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))

    if isinstance(dt, datetime.datetime):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.timestamp()

    if isinstance(dt, datetime.date):
        dt = datetime.datetime(
            dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc
        )
        return dt.timestamp()

    return value


def _classify_axis_for_range(
    seq: list[Any], bound: Any
) -> tuple[str, Optional[dict[Any, int]]]:
    """Classify an axis as 'numeric', 'datetime', 'categorical' or 'empty'.

    Returns a tuple of (kind, category_positions). For categorical axes the
    positions dict maps each unique label to an integer position so that
    repeated category values share the same axis position.
    """
    import datetime
    import numbers

    if not seq:
        return ("empty", None)

    sample = seq[0]

    if isinstance(sample, (datetime.datetime, datetime.date)) and (
        _is_datetime_like(bound)
    ):
        return ("datetime", None)
    if (
        isinstance(sample, str)
        and _is_datetime_like(sample)
        and _is_datetime_like(bound)
    ):
        return ("datetime", None)
    if (
        isinstance(sample, numbers.Number)
        and not isinstance(sample, bool)
        and isinstance(bound, numbers.Number)
        and not isinstance(bound, bool)
    ):
        return ("numeric", None)

    positions = {value: idx for idx, value in enumerate(dict.fromkeys(seq))}
    return ("categorical", positions)


def _axis_in_range_flags(data: Any, lo: Any, hi: Any) -> list[bool]:
    """Return a list of booleans for whether each value is within [lo, hi].

    Handles numeric, datetime (naive treated as UTC) and categorical axes.
    Categorical axes map labels to integer positions and each cell spans
    (position - 0.5, position + 0.5).
    """
    seq = list(data)
    kind, positions = _classify_axis_for_range(seq, lo)
    if kind == "empty":
        return []
    if kind == "datetime":
        lo_n = _to_numeric_coord(lo)
        hi_n = _to_numeric_coord(hi)
        return [lo_n <= _to_numeric_coord(v) <= hi_n for v in seq]
    if kind == "numeric":
        return [lo <= v <= hi for v in seq]
    assert positions is not None
    return [
        (hi > positions[v] - 0.5) and (lo < positions[v] + 0.5) for v in seq
    ]


def _axis_in_range_mask_numpy(data: Any, lo: Any, hi: Any) -> Any:
    """Numpy-accelerated equivalent of :func:`_axis_in_range_flags`."""
    import numpy as np

    seq = list(data)
    kind, positions = _classify_axis_for_range(seq, lo)
    if kind == "empty":
        return np.zeros(0, dtype=bool)
    if kind == "datetime":
        arr = np.array([_to_numeric_coord(v) for v in seq], dtype=float)
        return (arr >= _to_numeric_coord(lo)) & (arr <= _to_numeric_coord(hi))
    if kind == "numeric":
        arr = np.asarray(seq)
        return (arr >= lo) & (arr <= hi)
    assert positions is not None
    pos = np.array([positions[v] for v in seq])
    return (hi > pos - 0.5) & (lo < pos + 0.5)


def _scatter_axis_fields(figure: go.Figure) -> tuple[str, str]:
    """Return the (x, y) field names to use for scatter point payloads."""
    x_axes: list[go.layout.XAxis] = []
    figure.for_each_xaxis(x_axes.append)
    x_axis = x_axes[0] if len(x_axes) == 1 else None

    y_axes: list[go.layout.YAxis] = []
    figure.for_each_yaxis(y_axes.append)
    y_axis = y_axes[0] if len(y_axes) == 1 else None

    x_field = x_axis.title.text if (x_axis and x_axis.title.text) else "x"
    y_field = y_axis.title.text if (y_axis and y_axis.title.text) else "y"
    return x_field, y_field


def _build_scatter_point(
    trace: Any,
    trace_idx: int,
    idx: int,
    x_data: Any,
    y_data: Any,
    x_field: str,
    y_field: str,
) -> dict[str, Any]:
    """Build a scatter selection payload point for the given index."""
    x_val = _get_indexed_value(x_data, idx)
    y_val = _get_indexed_value(y_data, idx)

    point_dict: dict[str, Any] = {
        x_field: x_val,
        y_field: y_val,
        "curveNumber": trace_idx,
        "pointIndex": idx,
    }

    name = getattr(trace, "name", None)
    if name:
        point_dict["name"] = name

    return point_dict


def _bar_value_in_selection_range(
    trace: Any,
    point_idx: int,
    point_value: Any,
    selection_min: Any,
    selection_max: Any,
) -> bool:
    """Return whether a bar's value extent overlaps the selection range.

    A bar spans from its ``base`` (defaulting to 0) to ``base + value``. The
    bar is considered selected on the value axis if that extent overlaps
    [selection_min, selection_max].

    Returns ``False`` (never raises) when the point value or the trace base
    are non-numeric (e.g. string) values, since range membership cannot be
    determined for such values.
    """
    import numbers

    base = getattr(trace, "base", None)
    base_value: Any = 0
    if base is not None:
        indexed_base = _get_indexed_value(base, point_idx)
        base_value = 0 if indexed_base is None else indexed_base

    if not isinstance(point_value, numbers.Number) or isinstance(
        point_value, bool
    ):
        return False
    if not isinstance(base_value, numbers.Number) or isinstance(
        base_value, bool
    ):
        return False

    bar_low = base_value
    bar_high = base_value + point_value
    if bar_low > bar_high:
        bar_low, bar_high = bar_high, bar_low

    return bar_high >= selection_min and bar_low <= selection_max


def _point_in_polygon(
    x: float, y: float, poly_x: list[float], poly_y: list[float]
) -> bool:
    """Ray-casting point-in-polygon test."""
    n = len(poly_x)
    if n < 3:
        return False

    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly_x[i], poly_y[i]
        xj, yj = poly_x[j], poly_y[j]
        if ((yi > y) != (yj > y)) and (
            x < (xj - xi) * (y - yi) / (yj - yi) + xi
        ):
            inside = not inside
        j = i
    return inside


