+const SCATTER=new Set(["scatter","scattergl"]);
+const CLICK=new Set(["bar","heatmap","histogram"]);
+const STANDARD=["x","y","z","lat","lon","curveNumber","pointNumber","pointNumbers","pointIndex"];
+const getType=v=>typeof v?.type==="string"?v.type:undefined;
+const getMode=v=>typeof v?.mode==="string"?v.mode:undefined;
+
+function hasPureLineTrace(traces){return traces.some(t=>{const type=getType(t);if(!type||!SCATTER.has(type))return false;const mode=getMode(t);if(!mode)return false;return mode.includes("lines")&&!mode.includes("markers");});}
