+function shouldHandleClickSelection(points){if(!points||points.length===0)return false;return points.some(p=>{const type=getType(p.data);if(type&&CLICK.has(type))return true;if(type&&SCATTER.has(type))return getMode(p.data)===undefined;return false;});}
