+
+// createParser minimal
+function createParser(ht){const regex=/([^<=>]+)=%{([^}]+)}/g;const pairs={};let m;while((m=regex.exec(ht))!==null)pairs[m[1]]=m[2];const get=(data,sel)=>{ // simple selector: customdata[0], x
+  const mm=sel.match(/^([a-zA-Z_]+)\[(\d+)\]$/); if(mm)return data[mm[1]]?.[Number(mm[2])]; return data[sel];};
+  return {update(n){return n===ht?this:createParser(n);},parse(d){const acc={};for(const[k,s]of Object.entries(pairs))acc[k]=get(d,s);return acc;}};}
+
+function extractPoints(points){if(!points)return[];let parser;return points.map(point=>{const type=getType(point.data);if(type==="heatmap")return pick(point,["x","y","z"]);const ht=Array.isArray(point.data.hovertemplate)?point.data.hovertemplate[0]:point.data.hovertemplate;const std=pick(point,STANDARD);const fd=point.fullData;const fm=getMode(fd);const isLine=(type==="scatter"||type==="scattergl")&&fm!==undefined&&fm.includes("lines");let inf;if(isLine&&fd&&typeof point.pointNumber==="number"){const idx=point.pointNumber;inf={x:Array.isArray(fd.x)?fd.x[idx]:point.x,y:Array.isArray(fd.y)?fd.y[idx]:point.y,pointIndex:idx};}const base=inf?{...std,...inf}:std;if(!ht)return base;parser=parser?parser.update(ht):createParser(ht);const parsed=parser.parse(point);return inf?{...parsed,...base}:{...base,...parsed};});}
+
