+assert(hasPureLineTrace([{type:"bar"}])===false,"bar false");
+assert(hasPureLineTrace([{type:"scatter",mode:"markers"}])===false,"markers false");
+assert(hasPureLineTrace([{type:"scatter",mode:"lines+markers"}])===false,"lines+markers false");
+assert(hasPureLineTrace([{type:"scattergl",mode:"lines"}])===true,"scattergl lines true");
+
+// lineSelectionButtons
+let dm=[];const btns=lineSelectionButtons(m=>dm.push(m));
+assert(btns.length===2,"two buttons");
+assert(btns[0].name==="line-box-select","btn0 name");
+btns[0].click();assert(dm[0]==="select","btn0 select");
+assert(btns[1].name==="line-lasso-select","btn1 name");
+btns[1].click();assert(dm[1]==="lasso","btn1 lasso");
+
+// merge
+const r=mergeModeBarButtonsToAdd(["a","b"],["b","c",{name:"a",title:"",icon:{},click(){}}]);
+assert(JSON.stringify(r.filter(x=>typeof x==="string"))===JSON.stringify(["a","b","c"]),"merge strings dedup");
+assert(r.some(x=>typeof x!=="string"&&x.name==="a"),"merge keeps object even if string same name");
+
+// shouldHandleClickSelection
